"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["51587"],{77398(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_recurso_fase.ancora_em_ato_congelante","status":422,"titulo":"O evento que inicia o prazo do recurso da fase nunca \xe9 o ato que congela a configura\xe7\xe3o; escolha outro ato"},"descricao":{"codigo":"uniplus.selecao.regra_recurso_fase.ancora_em_ato_congelante","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["A regra de recurso de uma fase conta o prazo de interposi\xe7\xe3o a partir de um tipo de ato que\\n**congela a configura\xe7\xe3o** do processo seletivo, como a publica\xe7\xe3o do pr\xf3prio edital.","O ato que congela a configura\xe7\xe3o fixa as regras do certame e n\xe3o \xe9 uma decis\xe3o sobre\\ncandidato. Contar o prazo a partir dele faria a regra de recurso depender de um ato que nunca\\n\xe9 resultado, e a configura\xe7\xe3o de que a regra faz parte deixaria de ser\\nreproduz\xedvel. O recurso cab\xedvel \xe9 contra o **resultado preliminar** da fase, e \xe9 nele\\nque o prazo come\xe7a a correr."],"comoResolver":["A mensagem da recusa nomeia o tipo de ato declarado como in\xedcio do prazo. Aponte o prazo para o\\nresultado preliminar que a **pr\xf3pria fase** publica. Se ele ainda n\xe3o est\xe1 entre os\\nprodutos da fase, acrescente-o, com papel preliminar, e conte o prazo a partir dele.","Se o resultado preliminar \xe9 publicado por outra fase, a regra de recurso pertence a\\nela: mova a regra para l\xe1. O mesmo problema na regra de recurso da etapa tem\\n[p\xe1gina pr\xf3pria](/erros/uniplus.selecao.recurso_da_etapa.ancora_em_ato_congelante)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra recurso fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);